err_unpack_busy: "কনসোল এখন অন্য একটি ফাইল আনকম্প্রেস করছে। সেটি শেষ হওয়া পর্যন্ত অপেক্ষা করে আবার চেষ্টা করুন।",
err_unpack_mount: "কনসোল আনকম্প্রেস করার জন্য এই ফাইলটি খুলতে পারেনি। যদি ShadowMount+ এটি মাউন্ট করে রাখে বা এর কোনো গেম চলে, গেমটি বন্ধ করে আবার চেষ্টা করুন। কিছুই লেখা হয়নি।",
