backup_warning: "স্ন্যাপশট PS5-এ /data/ps5upload/backups/-এ রাখা হয়। পুনরুদ্ধার করলে বিদ্যমান ফাইল তাদের মূল পাথে ওভাররাইট হয়ে যায়।",
