bringup_phase_prehelper: "বুটস্ট্র্যাপ পেলোড লোড হচ্ছে ({name})…",
engine_url_hint: "অ্যাপটি কোথায় ps5upload-engine-এর সাথে যোগাযোগ করে। ডিফল্টভাবে স্থানীয় সাইডকারে রেখে দিন, অথবা একটি রিমোট/নিজে হোস্ট করা ইঞ্জিনে নির্দেশ করুন। স্থানীয় ও রিমোটের মধ্যে বদল করার পর অ্যাপ পুনরায় চালু করুন।",
err_fs_read_path_not_allowed: "এই ফাইলটি একটি রিড-অনলি সিস্টেম পার্টিশনে আছে যা সাধারণত ব্লক করা থাকে। /system, /system_data ও অন্যান্য সুরক্ষিত পাথ থেকে পড়তে সেটিংস → “সিস্টেম ফাইল ডাউনলোড করার অনুমতি দিন” চালু করুন। এটি শুধু ডাউনলোডে প্রযোজ্য — সেখানে মুছে ফেলা, সরানো ও লেখা কখনোই অনুমোদিত নয়।",
err_rar_open_failed: "এই RAR ফাইলটি পড়া যায়নি। এটি বহু-অংশের সেট হলে প্রথম অংশটি বেছে নিন (…part1.rar / …part01.rar / ….rar) এবং নিশ্চিত করুন সব অংশ একই ফোল্ডারে আছে। পাসওয়ার্ড থাকলে সেটি দিন।",
err_rar_password_required: "এই RAR ফাইলটি পাসওয়ার্ড দিয়ে সুরক্ষিত। এর বিষয়বস্তু পড়তে ও আপলোড করতে নিচে পাসওয়ার্ড দিন।",
err_rar_unsafe_entry: "এই RAR ফাইলে এমন ফাইল পাথ আছে যা গন্তব্য ফোল্ডারের বাইরে নির্দেশ করে, তাই নিরাপত্তার কারণে এটি প্রত্যাখ্যান করা হয়েছে। আর্কাইভটি ক্ষতিগ্রস্ত হতে পারে।",
err_rar_unsupported: "এই বিল্ডে RAR ফাইল সমর্থিত নয় (Android শুধু .zip ও .7z আপলোড করতে পারে)। অনুগ্রহ করে .rar আগে কম্পিউটারে খুলে নিন, অথবা ডেস্কটপ অ্যাপ ব্যবহার করুন।",
fs_download_zip_dialog_title: "“{name}” .zip হিসেবে সংরক্ষণ করুন",
fs_install_confirm_body_usb: "এটি প্যাকেজটি অভ্যন্তরীণ স্টোরেজে অস্থায়ীভাবে রাখে (কনসোল সরাসরি USB থেকে ইনস্টল করতে পারে না), ইনস্টল করে, তারপর অস্থায়ী কপিটি মুছে দেয়। আপনার ড্রাইভের মূল ফাইলে হাত দেওয়া হয় না।",
