fs_rename_target_exists: "এখানে ইতিমধ্যেই “{name}” নামে একটি আইটেম আছে — নাম বদলালে সেটি ওভাররাইট হয়ে যাবে। অন্য নাম বেছে নিন বা আগে সেটি মুছে ফেলুন।",
fw_spoof_kernel_unknown_warn: "কার্নেল সংস্করণ পড়া যায়নি — স্পুফ শনাক্তকরণ নির্ভরযোগ্য নাও হতে পারে।",
game_hub_launch_unconfirmed_body: "PS5 লঞ্চ কমান্ড গ্রহণ করেছে কিন্তু গেমটি এখনও দেখা যায়নি। কনসোল দেখুন — এটি এখনও চালু হচ্ছে থাকতে পারে।",
installed_launch_slow: "লঞ্চ কমান্ড পাঠানো হয়েছে — প্রথমবার চালু হতে কিছুটা সময় লাগতে পারে। একটু অপেক্ষা করে PS5-এ দেখে নিন।",
installed_stop_confirm_body: "এটি PS5-এ চলমান গেমটি বন্ধ করে দেবে। সংরক্ষণ না করা অগ্রগতি হারিয়ে যাবে — কনসোলে গেম থেকে বেরিয়ে আসার মতোই।",
installed_stop_confirm_title: "{name} বন্ধ করবেন?",
library_show_all: "সব {count}টি দেখান",
payloads_add_repo_hint: "owner/name (যেমন EchoStretch/kstuff-lite) অথবা একটি সম্পূর্ণ রিপোজিটরি URL পেস্ট করুন। কিউরেটেড এন্ট্রির মতো একইভাবে রিলিজ আনা হয়, ডাউনলোডে একই ELF/zip যাচাই প্রযোজ্য। শুধু বিশ্বস্ত রিপোজিটরি যোগ করুন — কাস্টম রিপোজিটরি কী প্রকাশ করে ps5upload তা যাচাই করে না।",
payloads_add_repo_host_hint: "শুধু তখনই ব্যবহৃত হয় যখন আপনি কেবল owner/name দেন। GitHub, অথবা একটি Gitea/Forgejo হোস্ট।",
