"pkglib.installnote.body": "ps5upload প্যাকেজটি PS5-এ নিজের ইনস্টলারের কাছে দেয় এবং কনসোল পুরো প্যাকেজটি পড়ে ফেলার পরেই কেবল ইনস্টল হয়েছে বলে জানায়; প্যাচের ক্ষেত্রে গেমের ভার্সনও বাড়তে হয়। ইনস্টল ব্যর্থ হলে প্যাকেজটি রেখে দেওয়া হয় যাতে আবার চেষ্টা করতে পারেন। FW 12+ এবং সিস্টেম প্যাকেজের জন্য এখনও PS5-এর সেটিংস → সিস্টেম → ডিবাগ সেটিংস → গেম → Package Installer লাগতে পারে।",
