imgbrowse_explain: "ps5upload যে কোনো গেম ইমেজ বা প্যাকেজ পড়তে পারে (.exfat, .ffpkg, .ffpfs, .ffpfsc, বা ডিবাগ কী দিয়ে তৈরি .pkg), তা যে কোনো কম্পিউটারে মাউন্ট না করেই ব্রাউজ করুন। কোনো ফাইল বা ফোল্ডার কম্পিউটারে সংরক্ষণ করুন, অথবা ফাইল বদলে একটি সম্পাদিত কপি লিখুন: আপনার খোলা ইমেজ কখনো বদলায় না।",
