localimage_explain: "এটি ইমেজটিকে এই কম্পিউটারে একটি সাধারণ ড্রাইভ হিসেবে খোলে, যাতে আপনি Finder বা Explorer দিয়ে ঠিক USB স্টিকের মতোই ভেতরের ফাইল — যেমন প্যাচ ফাইল — যোগ, প্রতিস্থাপন ও মুছতে পারেন। পরিবর্তনগুলি সরাসরি ইমেজ ফাইলে সংরক্ষিত হয়। ps5upload কখনও নিজে ইমেজে লেখে না; সেটি আপনার অপারেটিং সিস্টেম করে। কাজ শেষ হলে এখান থেকেই বের করে নিন।",
