upload_split_pick_entry_title: "এর বদলে \"{name}\" বেছে নিন",
upload_split_pick_entry_body: "এটি একটি বিভক্ত সেটের একটি ভলিউম, পুরো আর্কাইভ নয়। উপরের ফাইলটি বেছে নিন — বাকি ভলিউমগুলো আপনাআপনি পড়া হবে, আলাদা করে আপলোড করার দরকার নেই।",
