"pkg.reason.stream_unreachable": "প্যাকেজ আনতে PS5 কখনো এই কম্পিউটারে পৌঁছাতে পারেনি। এই কম্পিউটারের ফায়ারওয়ালে ps5upload-কে অনুমতি দিন (Windows-এ প্রাইভেট ও পাবলিক দুই নেটওয়ার্কের জন্য), কম্পিউটার ও PS5-কে VPN ছাড়া একই নেটওয়ার্কে রাখুন, এবং PS5-এর প্রক্সি সার্ভার “ব্যবহার করবেন না”-তে সেট করুন। আপলোড ও ইনস্টল এই সংযোগ ছাড়াই কাজ করে।",
"pkg.reason.stream_proxy": "PS5-এর প্রক্সি সেটিং স্ট্রিম আটকে দিয়েছে। PS5-এর নেটওয়ার্ক উন্নত সেটিংসে প্রক্সি সার্ভার “ব্যবহার করবেন না”-তে সেট করুন, অথবা আপলোড ও ইনস্টল ব্যবহার করুন, যা PS5-এর লোকাল স্টোরেজ থেকে প্যাকেজ পড়ে।",
