upload_warn_unsettled: "প্রতিটি বাইট কনসোলে পৌঁছেছে, কিন্তু সব ফাইল সংরক্ষণ হয়েছে বলে এখনও নিশ্চিত করেনি। সেগুলো নিজে থেকেই শেষ হবে; এর আগে কনসোলের বিদ্যুৎ চলে গেলে ফোল্ডারটি আবার পাঠান।",
