"joberr.ava1_refused": "PS5 এই অনুরোধ প্রত্যাখ্যান করেছে (কোড {code})। আবার চেষ্টা করুন; বারবার হলে হেল্পার ও অ্যাপ একই সংস্করণে আপডেট করুন এবং বাগ রিপোর্টে কোডটি দিন।",
"joberr.ava1_busy": "PS5 হেল্পার ব্যস্ত এবং সময়মতো এই ট্রান্সফার নেয়নি। এর অন্য কাজ শেষ হওয়া পর্যন্ত অপেক্ষা করে আবার চেষ্টা করুন-এ ক্লিক করুন।",
"joberr.ava1_unreachable": "PS5-এ পৌঁছানো যায়নি। এটি চালু আছে, একই নেটওয়ার্কে আছে এবং হেল্পার চলছে কি না দেখে আবার চেষ্টা করুন-এ ক্লিক করুন।",
"joberr.ava1_exists": "গন্তব্য PS5-এ আগে থেকেই আছে। প্রতিস্থাপনের জন্য ওভাররাইট বেছে নিন, অথবা অন্য গন্তব্য বেছে নিন।",
"joberr.ava1_commit_exists": "ফাইলটি আপলোড হয়েছে কিন্তু গন্তব্য আগে থেকেই থাকায় প্রকাশ করা যায়নি। প্রতিস্থাপনের জন্য ওভাররাইট বেছে নিন, অথবা অন্য গন্তব্য বেছে নিন।",
"joberr.ava1_cross_device": "গন্তব্য স্টেজিং এলাকা থেকে ভিন্ন ড্রাইভে, তাই PS5 ফাইলটি সরাতে পারেনি। একই ড্রাইভে গন্তব্য বেছে নিন, অথবা আগে অভ্যন্তরীণ ড্রাইভে আপলোড করুন।",
"joberr.ava1_wrong_console": "এই ঠিকানার ডিভাইসটি এই অ্যাপের সাথে পেয়ার করা PS5 নয়। ঠিকানা পরীক্ষা করুন, অথবা এই কনসোলের সাথে আবার পেয়ার করুন।",
"joberr.ava1_no_identity": "এই অ্যাপের এখনো পেয়ারিং পরিচয় নেই। সংযোগ স্ক্রিন থেকে PS5-এর সাথে পেয়ার করে আবার চেষ্টা করুন।",
"joberr.zip_read_error": ".zip ফাইলটি পড়া যায়নি (পড়ার সময় ফাইল বা তার ড্রাইভ সরে যেতে পারে)। উৎস এখনো সংযুক্ত আছে কি না দেখে আবার চেষ্টা করুন-এ ক্লিক করুন।",
"joberr.ava1_zip_corrupt": "এই .zip পড়া যায়নি: এটি ক্ষতিগ্রস্ত বা অসম্পূর্ণ। আবার ডাউনলোড বা তৈরি করে চেষ্টা করুন।",
"joberr.ava1_7z_corrupt": "এই .7z পড়া যায়নি: এটি ক্ষতিগ্রস্ত বা অসম্পূর্ণ। আবার ডাউনলোড বা তৈরি করে চেষ্টা করুন।",
"joberr.ava1_7z_encrypted": "এই .7z এনক্রিপ্টেড, তাই স্ট্রিম করা যায় না। আপনার কম্পিউটারে এক্সট্র্যাক্ট করে বদলে ফোল্ডারটি আপলোড করুন।",
"joberr.ava1_7z_unsafe_path": "এই .7z-এ একটি অনিরাপদ ফাইল পাথ আছে (নিজের ফোল্ডারের বাইরে যায়)। আপনার কম্পিউটারে এক্সট্র্যাক্ট করে বদলে ফোল্ডারটি আপলোড করুন।",
"joberr.rar_password": "এই .rar-এর জন্য পাসওয়ার্ড দরকার, অথবা দেওয়া পাসওয়ার্ড ভুল ছিল। সঠিক পাসওয়ার্ড দিয়ে আবার চেষ্টা করুন।",
"joberr.rar_corrupt": "এই .rar ক্ষতিগ্রস্ত, অথবা কিছু অংশ নেই বা ক্রমে নেই। সব অংশ আছে কি না নিশ্চিত করে আবার চেষ্টা করুন।",
"joberr.ava1_copy_lost": "PS5 এই কপির হদিস হারিয়েছে (হেল্পার রিস্টার্ট হয়েছে বা সংযোগ কেটেছে)। আবার শুরু করতে আবার চেষ্টা করুন-এ ক্লিক করুন।",
"joberr.ava1_copy_failed": "PS5 কপি শেষ করতে পারেনি। ফাঁকা জায়গা এবং উৎস ও গন্তব্য এখনো পাওয়া যাচ্ছে কি না দেখে আবার চেষ্টা করুন।",
"joberr.ava1_local_io": "এই কম্পিউটার ডাউনলোড করা ফাইল লিখতে পারেনি। গন্তব্য ফোল্ডারের অনুমতি ও ফাঁকা জায়গা দেখে আবার চেষ্টা করুন।",
"joberr.ava1_bad_manifest": "PS5 এমন একটি ফাইল তালিকা পাঠিয়েছে যা এই অ্যাপ বুঝতে পারেনি। হেল্পার ও অ্যাপ একই সংস্করণে আপডেট করে আবার চেষ্টা করুন।",
"joberr.helper_not_ava1": "PS5 হেল্পার চলছে না। সংযোগ স্ক্রিন থেকে এটি পাঠান (ব্যানার দিলে হেল্পার আপডেট করুন ব্যবহার করুন), তারপর আবার চেষ্টা করুন।",
"joberr.helper_not_ava1_web": "PS5 হেল্পার চলছে না। এই ওয়েব UI এটি পাঠাতে পারে না: আপনার সাধারণ পেলোড লোডার দিয়ে কনসোলে ps5upload পেলোড চালু করুন (ব্যানার দিলে হেল্পার আপডেট করুন ব্যবহার করুন), তারপর আবার চেষ্টা করুন।",
"joberr.not_paired": "এই PS5 এখনো এই অ্যাপ গ্রহণ করেনি। দুটিকে পেয়ার করুন (পেয়ার করুন… বোতাম), তারপর আবার চেষ্টা করুন।",
"joberr.helper_starting": "PS5 হেল্পার এখনো চালু হচ্ছে। কয়েক সেকেন্ড অপেক্ষা করে আবার চেষ্টা করুন।",
"joberr.ava1_failed": "PS5 হেল্পার চালু হয়েছে কিন্তু এর ট্রান্সফার সার্ভার চালু হয়নি। কনসোল রিস্টার্ট করে আবার চেষ্টা করুন।",
"joberr.helper_not_running": "PS5-এ কোনো হেল্পার চলছে না। আগে হেল্পার পাঠান (ডেস্কটপ অ্যাপের সংযোগ স্ক্রিন বা আপনার পেলোড লোডার), তারপর আবার চেষ্টা করুন।",
