kept_intro: "ps5upload নিজে এই কনসোলে যে ফোল্ডারগুলো লেখে এবং প্রতিটিতে কতটা আছে। অস্থায়ী ও পরীক্ষার ফাইল পরিষ্কার করা যায়; আপনার প্যাকেজ ও সেভ ব্যাকআপ এখান থেকে শুধু খোলা হয়, কখনও মোছা হয় না।",
