activity_description_v2: "অ্যাপ আপনার কনসোলগুলোতে যা করছে এবং করেছে তার সবকিছু: আপলোড, ডাউনলোড, ইনস্টল ও ফাইলের কাজ। এখান থেকে যেকোনোটি থামান বা আবার চেষ্টা করুন। সাম্প্রতিক ১০০টি রাখা হয়, রিস্টার্টের পরেও।",
fw_spoof_subtitle_v2: "এই PS5 যে ফার্মওয়্যার সংস্করণ জানায় তা কোনো স্পুফ পেলোড বদলেছে কি না পরীক্ষা করে, যাতে এর ওপর নির্ভরশীল কিছু ইনস্টলের আগে আপনি আসল সংস্করণ জানেন।",
health_subtitle_v2: "PS5, এই অ্যাপ এবং তাদের মধ্যকার নেটওয়ার্ক কাজ করছে কি না পরীক্ষা করে, না করলে কী ঠিক করতে হবে বলে, এবং তাদের মধ্যে ফাইল স্থানান্তরের গতি মাপে।",
remotePlay_subtitle_v2: "এই PS5-কে রিমোট প্লে-র জন্য সেটআপ করুন এবং সেই PIN নিন যা PS Remote Play অ্যাপকে এর সঙ্গে যুক্ত করে।",
saves_description_v2: "PS5-এর সেভ ডেটা, প্রতি গেমে একটি এন্ট্রি। কোনো গেমের সেভ এই কম্পিউটারে .zip-এ ব্যাকআপ নিন, এবং পরে পুনরুদ্ধার করুন।",
shell_description_v2: "এমন কমান্ড টাইপ করুন যা PS5-এ হেল্পার প্রসেসের ভেতরে চলে। অভিজ্ঞ ব্যবহারকারীদের জন্য। আউটপুট প্রতি কমান্ডে 256 KB-তে সীমিত; ওপর ও নিচের তীর আগের কমান্ড ফিরিয়ে আনে।",
"arcpkg.links.go": "{count}টি ফাইল ডাউনলোড করুন",
"arcpkg.links.help": "আর্কাইভের, অথবা ভাগ করা আর্কাইভের প্রতিটি অংশের সরাসরি লিংক পেস্ট করুন, প্রতি লাইনে একটি। ফাইলগুলো এই কম্পিউটারে (Downloads/ps5upload) ডাউনলোড হয়, যেখানে সবগুলোর জন্য জায়গা লাগে; তারপর ভেতরের প্যাকেজগুলো ওপরে বর্ণিতভাবে PS5-এ খোলা হয়।",
"arcpkg.links.kept": "ডাউনলোড করা {count}টি ফাইল {dir}-এ আছে। ইনস্টল আবার চেষ্টা করতে পারার জন্য এগুলো রাখা হয়; কাজ শেষ হলে মুছে ফেলুন।",
"arcpkg.links.progress": "{count}টির মধ্যে {n} নম্বর ফাইল এই কম্পিউটারে ডাউনলোড হচ্ছে…",
"arcpkg.links.title": "আর্কাইভটি ডাউনলোড লিংকে আছে",
"arcpkg.noFirstPart": "ফাইলগুলো ডাউনলোড হয়েছে, কিন্তু কোনোটিই আর্কাইভের প্রথম অংশ নয় (.zip, .7z, .rar বা .part1.rar)। লিংকগুলো পরীক্ষা করুন।",
"fpkg.image.done": "গেম ইমেজ লেখা হয়েছে এবং ফিরিয়ে পড়ে যাচাই করা হয়েছে। এটি PS5-এর ড্রাইভে কপি করুন («আপলোড»), ShadowMount+ এটি মাউন্ট করবে।",
"fpkg.image.what": "একটি ফাইল যা আপনি PS5 ড্রাইভে কপি করেন, ShadowMount+ সেটি মাউন্ট করে হোম স্ক্রিনে দেখায়। কিছুই ইনস্টল হয় না।",
"fpkg.image.folderOnly": "শুধু এই কম্পিউটারের গেম ফোল্ডারই গেম ইমেজ হতে পারে।",
"fpkg.image.folderOnly_v2": "শুধু একটি গেম ফোল্ডার (এই কম্পিউটারে, সংরক্ষিত সার্ভারে বা PS5-এ) গেম ইমেজ হতে পারে।",
"fpkg.image.folderOnly_v4": "শুধু গেম ফোল্ডার, গেম ইমেজ বা গেমসহ আর্কাইভ (.zip, .7z, .rar) গেম ইমেজ হতে পারে; আর্কাইভ আগে আউটপুট ফোল্ডারে খোলা হয়।",
