"fpkg.make.pkg_body": "স্টোরের গেমের মতো PS5-এ ইনস্টল হয়, এখান থেকে স্ট্রিম করে বা আগে আপলোড করে। PS4 গেম যেকোনো ফার্মওয়্যারে চলে; PS5 গেম 11.60 বা নিচে।",
