connection_payload_engine_unreachable: "অ্যাপটি এই কম্পিউটারে নিজের ইঞ্জিনে পৌঁছাতে পারেনি, তাই PS5-এ হেল্পার চালু হয়েছে কি না জানে না। এটি PS5-এর সমস্যা নয়: উইন্ডোর ওপরের বিজ্ঞপ্তি কারণ জানায় এবং ইঞ্জিন আবার চালু করতে পারে। তারপর আবার «হেল্পার পাঠান» চাপুন। ({error})",
"engine_problem.missing.fix": "অ্যান্টিভাইরাসের কোয়ারেন্টাইন থেকে ps5upload-engine ফিরিয়ে আনুন (বা অনুমতি দিন), অথবা অ্যাপটি আবার ইনস্টল করুন।",
"engine_problem.missing.why": "অ্যাপের ফোল্ডারে ইঞ্জিন প্রোগ্রামটি নেই। নিরাপত্তা সফটওয়্যার কখনো কখনো এটি কোয়ারেন্টাইন করে।",
"engine_problem.port.fix": "«ইঞ্জিন আবার চালু করুন» চাপুন। তাতে না হলে ফায়ারওয়াল বা অ্যান্টিভাইরাসে ps5upload-engine-কে অনুমতি দিন, তারপর অ্যাপটি আবার চালু করুন।",
"engine_problem.port.why": "কিছু একটা ইঞ্জিনের ঠিকানা ({url}) দখল করে আছে কিন্তু সাড়া দিচ্ছে না: সেই পোর্টে অন্য কোনো প্রোগ্রাম, বা সংযোগ আটকে রাখা নিরাপত্তা সফটওয়্যার।",
"engine_problem.proxy.fix": "লোকাল ঠিকানার (127.0.0.1) জন্য প্রক্সি বা VPN টুল বন্ধ করুন, অথবা http_proxy / ALL_PROXY সেটিং ছাড়া অ্যাপ চালু করুন।",
"engine_problem.proxy.why": "ইঞ্জিনের অনুরোধগুলো ইঞ্জিনের বদলে এই কম্পিউটারে সেট করা একটি প্রক্সিতে গেছে।",
"engine_problem.remote.fix": "দেখুন ইঞ্জিন (Docker কন্টেইনার বা অন্য কম্পিউটার) চলছে এবং সেই ঠিকানায় পৌঁছানো যায় কি না, অথবা «সেটিংস»-এ ঠিকানা বদলান।",
"engine_problem.remote.why": "এই অ্যাপ যে ইঞ্জিন ({url}) ব্যবহার করার জন্য সেট আছে, সেটি সাড়া দিচ্ছে না।",
"engine_problem.restart": "ইঞ্জিন আবার চালু করুন",
"engine_problem.slow.fix": "«ইঞ্জিন আবার চালু করুন» চাপুন। লোকাল সংযোগ ফিল্টার করা ফায়ারওয়াল বা অ্যান্টিভাইরাসও এর কারণ হতে পারে: ps5upload-engine-কে অনুমতি দিন।",
