"engine_problem.web.fix": "দেখুন সার্ভার (Docker কন্টেইনার) চলছে কি না, তারপর এই পেজটি আবার লোড করুন।",
"engine_problem.web.why": "এই পেজটি যে ps5upload সার্ভার থেকে এসেছে, তার সাথে সংযোগ হারিয়েছে।",
gate_engine_down_body_v2: "এই স্ক্রিনের জন্য অ্যাপের ইঞ্জিন দরকার, যেটি সাড়া দিচ্ছে না। উইন্ডোর ওপরের বিজ্ঞপ্তি কারণ জানায় এবং এটি আবার চালু করতে পারে।",
"profile.np.body": "Sony-র সাথে যোগাযোগ না করেই PS5 সাইন-ইন করা অ্যাকাউন্টকে PlayStation Network-এ সাইন ইন করা বলে ধরে নেয়। কনসোলের কিছু ফিচার কেবল সাইন-ইন করা অ্যাকাউন্টের জন্য খোলে, রিমোট প্লে তার একটি। এটি earthonion-এর np-fake-signin ব্যবহার করে, যা বোতাম চাপলে তার প্রজেক্ট পেজ থেকে আনা হয়।",
