trace_what: "গেম যেভাবে খেলে সেভাবে লোড হওয়া LZ4 গেম ইমেজের জন্য। ampr_emu-এর একটি মাপার বিল্ড খেলার সময় পড়া প্রতিটি ফাইল রেকর্ড করে; সেই সেশন থেকে বানানো প্রোফাইল প্রতিটি ফাইলের ব্লক সাইজ, লেআউট ও ক্যাশ বেছে নেয়, সবার জন্য একটি অনুমান নয়। এই গেমের LZ4 ইমেজ বানালে Convert এটি ব্যবহার করে।",
