"collection.junk_body": "Mac যা কিছু কপি করে তার পাশে লুকানো ফাইল রেখে যায়: exFAT ড্রাইভে প্রতিটি ফাইলের জন্য একটি \"._\" ফাইল (প্রতিটি পুরো একটি ক্লাস্টার দখল করে), সঙ্গে .DS_Store, .localized ও Icon ফাইল। কোনো কনসোল এগুলো পড়ে না। \"._\" ফাইল তখনই মোছা হয় যখন সেটি সত্যিই এমন একটি; আর কিছু ছোঁয়া হয় না।",
