"collection.copy_link_hint_v2": "এমন একটি লিংক যা থেকে এই PS5 নিজেই প্যাকেজ ইনস্টল করতে পারে (কনসোলের ব্রাউজার বা প্যাকেজ ইনস্টলার)। এই কম্পিউটার চালু থাকা পর্যন্ত কাজ করে, যতক্ষণ না আপনি পরিবেশন-এ থামান বা অ্যাপ বন্ধ হয়।",
