"collection.serving_body_v2": "যে PS5 নিজে নিয়ে নেয়, তাকে এই কম্পিউটার যে প্যাকেজগুলো পরিবেশন করছে। লিংক সেই PS5-এর জন্য কাজ করে যার জন্য তৈরি (অনুমতি দিলে নেটওয়ার্কের যেকোনো ডিভাইসের জন্য), যতক্ষণ না আপনি থামান বা অ্যাপ বন্ধ হয়।",
