a11y_motion_hint_v2: "স্বয়ংক্রিয় আপনার OS সেটিং অনুসরণ করে। কমানো স্ক্রিন বদলের অ্যানিমেশন বন্ধ করে এবং পপ-আপ অ্যানিমেশন ছোট করে; কোনোটি নয় সব অ্যানিমেশন ও ট্রানজিশন বন্ধ করে।",
