about_feat_cheats_body: "একটি গেম বেছে নিন, এর সংস্করণের জন্য তৈরি চিট ডাউনলোড করুন, তারপর খেলার সময় সেগুলো চালু করুন।",
about_feat_cheats_title: "চিট",
about_feat_console_body: "নেটওয়ার্কে রেস্ট মোড, রিস্টার্ট, শাট ডাউন ও জাগানো, সাথে চলমান প্রসেস, ফ্যান কার্ভ এবং হার্ডওয়্যারের সংক্ষিপ্ত বিবরণ।",
about_feat_console_title: "কনসোল নিয়ন্ত্রণ",
about_feat_convert_body: "গেম ফোল্ডার বা ইমেজকে ইনস্টলযোগ্য প্যাকেজে রূপান্তর করুন, অথবা একটি ফোল্ডারকে এমন গেম ইমেজে যা ShadowMount+ মাউন্ট করে।",
about_feat_convert_title: "গেম রূপান্তর",
about_feat_install_body: "এই কম্পিউটার, NAS শেয়ার, USB ড্রাইভ বা লিংক থেকে PS4 .pkg এবং PS5 ফেক প্যাকেজ (বেস, আপডেট, DLC)। PS5 একটি পথ প্রত্যাখ্যান করলে অ্যাপ অন্য পথ প্রস্তাব করে।",
about_feat_install_title: "প্যাকেজ ইনস্টল",
about_feat_payloads_body: "ক্যাটালগ থেকে বা আপনার নিজের ফাইল থেকে পেলোড ELF কনসোলের লোডারে পাঠান, একটি একটি করে বা প্লেলিস্ট হিসেবে।",
about_feat_payloads_title: "পেলোড",
about_feat_saves_body: "গেমের সেভ এই কম্পিউটারে একটি .zip-এ ব্যাকআপ নিন এবং পরে রিস্টোর করুন।",
about_feat_saves_title: "সেভ ডেটা",
activity_cancel_tooltip: "এই অপারেশন বাতিল করুন",
activity_clear_shown_confirm_body: "এখানে দেখানো শেষ হওয়া এন্ট্রিগুলো (সম্পন্ন, ব্যর্থ, থামানো) সরিয়ে দেয়। অন্য কনসোলের ইতিহাস এবং এখনো চলমান যেকোনো কিছু রাখা হয়। একটি সারি মুছতে তার ট্র্যাশ বোতাম ব্যবহার করুন।",
