"always_overwrite_hint_v2": "আপলোডের গন্তব্যে আগে থেকেই ফাইল থাকলে নিশ্চিতকরণ বাদ দিন। Override / Resume / Cancel প্রম্পট দেখতে বন্ধ রাখুন।",
audit_empty_v2: "এখনো কিছু রেকর্ড হয়নি। পাওয়ার অ্যাকশন (জাগানো, রেস্ট মোড, রিস্টার্ট, শাট ডাউন), মোছা, আনরেজিস্টার, আনইনস্টল এবং ইনস্টল আপনি করার সাথে সাথে এখানে দেখা যাবে।",
audit_log_description_v3: "এই কম্পিউটারে এই অ্যাপে রাখা পাওয়ার অ্যাকশন, মোছা, আনরেজিস্টার, আনইনস্টল এবং ইনস্টলের একটি রেকর্ড। নতুনতম 256টি রাখা হয় এবং পুরোনোগুলো বাদ পড়ে; মোছার কোনো বোতাম নেই, তবে অ্যাপের ডেটা বা ব্রাউজার স্টোরেজ মুছলে এটি মুছে যায়। শেষ 100টি দেখানো হয়।",
