autoloader_warn_none_v2: "সংযোগের সময় চালানোর জন্য একটি প্লেলিস্ট বেছে নিন।",
backup_explain_v2: "ফাইলগুলো কনসোলের নিজস্ব স্টোরেজে একটি স্ন্যাপশটে কপি করে যাতে পরে ফিরিয়ে রাখতে পারেন। নিচ থেকে একটি সাধারণ বিকল্প বেছে নিন, বা নিজের পাথ টাইপ করুন।",
backup_limit_depth: "আপনার বেছে নেওয়া ফোল্ডার থেকে {n} স্তরের বেশি নিচের ফোল্ডার বাদ দেওয়া হয়।",
backup_limit_flatten: "ফাইলগুলো তাদের পাথের নামে রাখা হয় যেখানে প্রতিটি / কে _ করা হয়, তাই দুটি আলাদা পাথ একই নামে পরিণত হতে পারে (a/b_c এবং a_b/c) এবং তাদের মধ্যে শুধু একটি রাখা হয়।",
backup_limit_keep: "প্রতিটি নামের শুধু নতুনতম {n}টি স্ন্যাপশট রাখা হয়; আরেকটি তৈরি করলে সবচেয়ে পুরোনোটি মুছে যায়।",
backup_subtitle_v3: "ফাইল ও ফোল্ডার PS5-এই রাখা একটি স্ন্যাপশটে কপি করুন, এবং পরে ফিরিয়ে রাখুন। এই কম্পিউটারে কিছুই কপি হয় না। গেম সেভের জন্য সেভ ডেটা ব্যবহার করুন।",
bandwidth_cap_clear: "সীমা সরান",
bandwidth_cap_on_hint_v2: "পরবর্তী শুরু হওয়া আপলোড থেকে সব আপলোড মিলিয়ে প্রায় {n} MB/s-এ সীমিত থাকে। সীমা সরাতে 0 সেট করুন।",
beta_features_hint_v2: "কোনো থাকলে সাইডবারে নির্মাণাধীন স্ক্রিন যোগ করে। এগুলো ব্যবহারযোগ্য কিন্তু এখনো নির্ভরযোগ্য নয়, এবং বদলাতে বা সরানো হতে পারে।",
bringup_desc_v2: "প্রতিটি বুটের জন্য, পেলোড-এ আপনার প্লেলিস্ট সেট হয়ে গেলে: আপনার ব্রিং-আপ প্লেলিস্ট (kstuff, ShadowMount+…) চালায়, ধাপ 2-এর মতোই হেল্পার পাঠায়, তারপর আপনার অটো-লোডার প্লেলিস্ট চালায়।",
changelog_description_v2: "এই সংস্করণ পর্যন্ত প্রতিটি ps5upload সংস্করণের রিলিজ নোট, অ্যাপের সাথে বান্ডল করা। নতুন রিলিজ ও সেগুলোর ডাউনলোড GitHub-এ আছে।",
