companion_suggest_body_v2: "ps5upload kstuff (কার্নেল এক্সপ্লয়েট), ShadowMount+ (গেম ব্যাকআপ অটো-মাউন্ট) এবং আরও ডজনখানেক হোমব্রু পেলোডের সাথে কাজ করে। পেলোড → ক্যাটালগ এক ক্লিকে সেগুলো পাঠায়।",
companion_suggest_open_payloads: "পেলোড খুলুন",
connection_first_run_nudge_body_v2: "সেটআপ উইজার্ড kstuff ও ShadowMount+ ডাউনলোড করে পাঠায়, তারপর হেল্পার, সঠিক ক্রমে। আপনার কনসোল যদি নিজেই kstuff লোড করে (একটি autoloader, etaHEN), তাহলে নিচের ধাপ 2 শুধু হেল্পার পাঠায়।",
