first_run_description_v3: "বেশিরভাগ সেটআপের যা দরকার তা সঠিক ক্রমে লোড করে: kstuff (ফেক প্যাকেজ ইনস্টল ও চালাতে দেয়), ShadowMount+ (গেম ইমেজ ও ফোল্ডার PS5-এর হোম স্ক্রিনে রাখে) এবং ps5upload-এর নিজস্ব হেল্পার। PS5 রিস্টার্ট হওয়ার পর সংযোগ আবার এই উইজার্ড প্রস্তাব করে।",
