game_activity_no_console_playtime: "কনসোল খেলার সময় নেই",
game_activity_subtitle_v3: "এই PS5-এ কী খেলা হয়েছে এবং কতক্ষণ। ট্র্যাক করা খেলার সময় কনসোলে ps5upload হেল্পার গণনা করে; কনসোল খেলার সময় কনসোলের নিজস্ব রেকর্ড থেকে পড়া হয়।",
hardware_description_v2: "হেল্পার সংযুক্ত থাকাকালীন সিস্টেম তথ্য, আপটাইম এবং স্টোরেজ প্রতি 5 সেকেন্ডে স্বয়ংক্রিয়ভাবে রিফ্রেশ হয়। লাইভ তাপমাত্রা ও CPU ক্লক চাহিদামতো পড়া হয় — রিড সেন্সর-এ ক্লিক করুন। রিটেইল ফার্মওয়্যার সব রিডিং দেয় না (যেমন CPU ব্যবহার); সেগুলো ড্যাশ হিসেবে দেখায়।",
