hw_fan_confirm_msg: "কনসোলের ফ্যান নিয়ন্ত্রণ এই তাপমাত্রা ধরে রাখার চেষ্টা করবে, এবং প্রতিবার হেল্পার লোড হলে ps5upload এটি আবার সেট করে। কম মানে বেশি শব্দ; বেশি মান কনসোলকে বেশি গরমে চলতে দেয়।",
