hw_kernel_log_link: "PS5 সিস্টেম লগ (কার্নেল): লগ → কার্নেল খুলুন",
hw_sensor_no_reading: "কনসোল এই সেন্সরের কোনো রিডিং দেয়নি",
keep_ps5_awake_mode_hint_v2: "PS5-এর অটো-স্ট্যান্ডবাই টাইমার নিয়মিত রিসেট করে যাতে এটি রেস্ট মোডে না যায়। “আপলোড ও ইনস্টলের সময়” দীর্ঘ আপলোড রক্ষা করে (ব্যর্থ আপলোডের একটি সাধারণ কারণ; ডিফল্ট)। “সর্বদা সংযুক্ত থাকা অবস্থায়” অ্যাপ খোলা থাকা পর্যন্ত চলমান হেল্পারসহ প্রতিটি কনসোলকে রেস্ট মোডের বাইরে রাখে। হাতে PS5 রেস্ট মোডে দেওয়া সব মোডেই কাজ করে।",
kernellog_categories_explainer: "প্রতিটি বিভাগ শুরুতে দেখানো থাকে। Sony-র বিভাগগুলো কনসোলের নিজস্ব সাবসিস্টেম, যা প্রতিটি জেলব্রোকেন PS5-এ, যে পেলোডই চলুক, অবিরাম লগ করে; এগুলো ps5upload-এর কারণে নয়। গোলমাল কমাতে এগুলোর টিক তুলে দিন।",
