payloads_description_catalog_v2: "বাছাই করা থার্ড-পার্টি PS5 হোমব্রু পেলোড। সর্বশেষ রিলিজ দেখুন, একবার ডাউনলোড করুন, তারপর এক ক্লিকে আপনার PS5-এ পাঠান। সংস্করণগুলো লোকালি ক্যাশ হয় যাতে আপনি সেগুলো USB পেলোড স্টিকেও রাখতে পারেন।",
payloads_description_send_v2: "যেকোনো PS5 পেলোড ফাইল — .elf, .bin, .js, .lua বা .jar (kstuff, কাস্টম হোমব্রু লোডার, ব্রাউজার-স্টেজ এক্সপ্লয়েট, প্লাগইন স্ক্রিপ্ট, BD-JB JAR) — আপনার PS5-এ পাঠান। সংযোগ স্ক্রিনের মতোই প্রক্রিয়া, শুধু আপনার বেছে নেওয়া ফাইলের দিকে। পোর্ট ফাইলের ধরন অনুসরণ করে (.elf/.bin 9021, .jar 9025, .lua 9026, .js 50000); আপনার লোডার অন্য কোথাও শুনলে তবেই এটি বদলান।",
payloads_download_failed: "ডাউনলোড ব্যর্থ: {id}",
