processes_kill_payload_body: "এটি পেলোড “{name}” (kstuff, etaHEN ইত্যাদি) বন্ধ করে দেয়। এটি যা সরবরাহ করে তা আবার না পাঠানো পর্যন্ত বন্ধ থাকে, এবং যেসব গেমের এটি দরকার সেগুলো শুরু হওয়া বন্ধ হতে পারে।",
