"profile.np.browser_v2": "সাইন ইন করতে ডেস্কটপ অ্যাপ লাগে: এটি np-fake-signin এনে PS5-এ পাঠায়, যা ওয়েব UI পারে না।",
ps5notif_empty_hint_v2: "ps5upload যখন আপনার টিভিতে কোনো বার্তা দেখায়, যেমন রিমোট প্লে PIN বা কোনো চিট চালু হওয়া, তখন তা এখানে তালিকাভুক্ত হয় যাতে আবার পড়তে পারেন। এটি PS5-এর নিজস্ব নোটিফিকেশন প্যানেল নয়; কনসোল আমাদের সেটি পড়তে দেয় না।",
reset_confirm_body_browser: "এই ব্রাউজার PS5Upload-এর জন্য যে সব সেটিং ও সংরক্ষিত অবস্থা রাখে তা মুছে দেয়, এবং পেজ নতুন করে লোড হয়। সার্ভারে ইঞ্জিনের নিজস্ব ডেটা (কনসোল পেয়ারিং, সংগ্রহ, সংরক্ষিত সার্ভার, ব্যাকপোর্ট লাইব্রেরি, ইনস্টল ইতিহাস, লগ) স্পর্শ করা হয় না, আপনার PS5-এর কিছুও না। এটি পূর্বাবস্থায় ফেরানো যায় না।",
reset_confirm_body_v2: "এটি PS5Upload-এর সমস্ত লোকাল ডেটা স্থায়ীভাবে মুছে দেয়: সেটিংস, আপনার সংরক্ষিত PS5 ও তাদের পেয়ারিং, সংগ্রহ, সংরক্ষিত সার্ভার ও তাদের পাসওয়ার্ড, ব্যাকপোর্ট লাইব্রেরি, ইনস্টল ইতিহাস, জব ও ইভেন্ট, কার্যকলাপ/কিউ ইতিহাস, লগ, পেলোড ক্যাশ এবং ক্র্যাশ রিপোর্ট। এটি আপনার PS5-এর কিছুই স্পর্শ করে না। অ্যাপ নতুন অবস্থায় আবার লোড হয়। এটি পূর্বাবস্থায় ফেরানো যায় না।",
reset_hint_browser: "এই ব্রাউজার PS5Upload-এর জন্য যে সব সেটিং ও সংরক্ষিত অবস্থা রাখে তা মুছে নতুন করে শুরু করুন। ইঞ্জিন তার সার্ভারে যা রাখে (কনসোল পেয়ারিং, সংগ্রহ, সংরক্ষিত সার্ভার, ব্যাকপোর্ট লাইব্রেরি, ইনস্টল ইতিহাস, লগ) তা স্পর্শ করা হয় না, এবং আপনার PS5-এর কিছুই প্রভাবিত হয় না।",
reset_hint_v2: "PS5Upload-এর প্রতিটি লোকাল চিহ্ন মুছে নতুন করে শুরু করুন: সেটিংস, সংরক্ষিত PS5 ও তাদের পেয়ারিং, সংগ্রহ, সংরক্ষিত সার্ভার ও তাদের পাসওয়ার্ড, ব্যাকপোর্ট লাইব্রেরি, ইনস্টল ইতিহাস, জব ও ইভেন্ট, কার্যকলাপ/কিউ ইতিহাস, লগ, পেলোড ক্যাশ এবং ক্র্যাশ রিপোর্ট। আপনার PS5-এর কিছুই প্রভাবিত হয় না। উপরের ব্যাকআপ / রিস্টোর পেয়ারিং, সংগ্রহ, সার্ভার পাসওয়ার্ড বা ব্যাকপোর্ট লাইব্রেরি অন্তর্ভুক্ত করে না।",
saves_backup_usb_tooltip_v2: "সেটিংসে সেট করা সেভ পাথে ড্রাইভে (PS5-এ একটি USB ড্রাইভ) এই সেভটি zip করুন। এটি এই কম্পিউটারে কপি, zip করে ফেরত পাঠানো হয়, তাই অ্যাপ খোলা রাখুন; এখানকার কপি পরে মুছে ফেলা হয়।",
saves_description_browser: "PS5-এর সেভ ডেটা, প্রতিটি গেমের জন্য একটি এন্ট্রি। সেভ .zip-এ ব্যাকআপ নেওয়া ও রিস্টোর করতে ডেস্কটপ অ্যাপ লাগে; এখানে আপনি সেগুলো দেখতে ও তাদের ফোল্ডার খুলতে পারেন।",
saves_restore_usb_tooltip_v2: "সেটিংসে সেট করা সেভ পাথে এর সর্বশেষ ব্যাকআপ থেকে এই সেভ রিস্টোর করুন। zip এই কম্পিউটারে কপি, আনপ্যাক করে PS5-এ ফেরত পাঠানো হয়, তাই অ্যাপ খোলা রাখুন। বর্তমান সেভ ওভাররাইট করে।",
