settings_artwork_cache_explain_v2: "গেম কভার ইঞ্জিন যেখানে চলে সেখানে রাখা হয় (এই কম্পিউটার, বা ওয়েব সংস্করণের জন্য সার্ভার) যাতে প্রতিবার আপনার PS5 থেকে পড়ার বদলে সেগুলো সাথে সাথে লোড হয়। এগুলো স্বয়ংক্রিয়ভাবে রিফ্রেশ হয়, এবং কোনো কনসোলে গেম ইনস্টল বা আনইনস্টল করলে সেই কনসোলের জন্য সরানো হয়।",
