auto_bringup_hint: "সংরক্ষিত কোনো PS5-এর লোডার (elfldr, পোর্ট 9021) চালু থাকলে এবং হেল্পার না চললে অ্যাপ নিজেই দ্রুত ব্রিং-আপ চালায়: আপনি সেট করলে আপনার ব্রিং-আপ প্লেলিস্ট, তারপর হেল্পার, তারপর আপনার অটো-লোডার প্লেলিস্ট। কনসোল প্রতিবার চালু হলে একবার; রেস্ট মোডের পরে শুধু হেল্পার আবার পাঠানো হয়। লোডার দেখা দেওয়ার পর প্রায় 90 সেকেন্ড অপেক্ষা করে, যাতে কনসোলের নিজের অটোলোডার আগে শেষ করতে পারে। ডিফল্টে বন্ধ।",
bringup_auto_hint_short: "PS5-এর লোডার চালু থাকলে এবং হেল্পার না চললে এটি নিজেই চালায়, লোডার দেখা দেওয়ার প্রায় 90 সেকেন্ড পরে। কনসোল প্রতিবার চালু হলে একবার।",
settings_card_install_fallback: "যখন PS5 কোনো প্যাকেজ আনতে পারে না",
settings_card_system_files: "সিস্টেম ফাইল",
settings_file_hint_v2: "প্রধান পছন্দগুলো (থিম, ভাষা, ইঞ্জিন, সেভ পাথ, আপলোড ডিফল্ট, অ্যাক্সেসিবিলিটি, সাইডবার) এই JSON ফাইলে প্রতিফলিত হয়। আপনি হাতে এটি এডিট করতে পারেন; পরেরবার অ্যাপ চালু করলে এডিট কার্যকর হয়। এতে সবকিছু থাকে না: আপনার সব পছন্দ নিয়ে যেতে ব্যাকআপ / রিস্টোর ব্যবহার করুন।",
