settings_schedule_label_placeholder_v2: "লেবেল (যেমন সেভ ব্যাকআপ)",
settings_updates_browser_note: "এই ওয়েব পেজ ps5upload ইঞ্জিন পরিবেশন করে এবং এর সাথেই আপডেট হয়: নতুন Docker ইমেজ pull করুন (অথবা আপনার সার্ভারে ইঞ্জিন আপডেট করুন) এবং এটি রিস্টার্ট করুন।",
"show_file_list_hint_v2": "অগ্রগতি বারের নিচে আপলোড হওয়া ফাইলের তালিকা দেখান। হাজারো ফাইলের ফোল্ডারে তালিকা ঝামেলার মনে হলে বন্ধ করুন — মোট অগ্রগতি, গতি ও বাকি সময় তবুও দেখবেন।",
show_file_list_v2: "আপলোডের সময় ফাইল তালিকা দেখান",
stats_description_v2: "এই কনসোলের জন্য দেখানো অপারেশনগুলোর মোট। অ্যাপ শেষ {count}টি রাখে, তাই পুরোনোগুলো গণনা হয় না। লোকাল ইতিহাস থেকে হিসাব করা; আপনার মেশিন থেকে কিছুই বাইরে যায় না।",
status_keep_awake_tooltip_v2: "জাগিয়ে রাখা “সর্বদা সংযুক্ত থাকা অবস্থায়” সেট আছে — অ্যাপ খোলা থাকা পর্যন্ত সংযুক্ত কনসোল স্বয়ংক্রিয়ভাবে রেস্ট মোডে যাবে না। সেটিংস → কনসোল-এ বদলান।",
update_idle_v2: "এখনো পরীক্ষা করা হয়নি। স্বয়ংক্রিয় পরীক্ষা চালু থাকলে অ্যাপ চালুর সময় ব্যাকগ্রাউন্ডে দেখে, দিনে সর্বোচ্চ একবার।",
upload_auto_resume_hint_browser: "ট্রান্সফারের মাঝে আপলোড ছিন্ন হলে, PS5-এর হেল্পার আবার সাড়া দিলেই যেখানে থেমেছিল সেখান থেকে আবার শুরু করুন, হাল ছাড়ার আগে কয়েকবার চেষ্টা করে। এই পেজ নিজে হেল্পার আবার পাঠাতে পারে না: PS5 রিস্টার্ট হলে আগে সেটি আবার পাঠান। PS5-এর জায়গা ফুরিয়ে যাওয়ার মতো গুরুতর সমস্যায় সাথে সাথে থেমে যায়। ডিফল্টভাবে চালু।",
upload_wake_for_uploads: "অপেক্ষমাণ আপলোডের জন্য PS5 জাগান",
upload_wake_for_uploads_hint: "কোনো আপলোড রেস্ট মোডে থাকা PS5-এর জন্য অপেক্ষা করলে সেটিকে জাগানোর সংকেত পাঠান এবং হেল্পার ফিরে এলেই চালিয়ে যান। শুধু সেই কনসোলের জন্য যেগুলিতে সংযোগ স্ক্রিনে জাগানো সেট করা আছে। ডিফল্টভাবে চালু।",
upload_picker_from_ps5_hint: "অন্য PS5 থেকে কপি করছেন? ফাইল সিস্টেমে ফাইলগুলো নির্বাচন করুন এবং অন্য কনসোলে পাঠান বেছে নিন।",
