"pkg.reason.staged_refused": "PS5 নিজের স্টোরেজ থেকে এই প্যাকেজটি নিতে অস্বীকার করেছে। 6.3.1-এর আগে ps5upload-এর একটি বাগের কারণে এটি হতো, যা ঠিক করা হয়েছে, তাই এটি আর হওয়ার কথা নয়; এটি ফাইলের কোনো সমস্যা নয়। আবার দেখলে, একটি কম্পিউটার থেকে (ডেস্কটপ অ্যাপ, বা হোম সার্ভারের ওয়েব UI) স্ট্রিম ও ইনস্টল দিয়ে ইনস্টল করুন এবং আমাদের একটি বাগ রিপোর্ট পাঠান।",
