"pkglib.staged_install_note": "PS5-এর নিজস্ব স্টোরেজ থেকে ইনস্টল হচ্ছে (FW {fw})… কিছু ফার্মওয়্যার এই পথে আসা প্যাকেজ অস্বীকার করে। অস্বীকৃত হলে প্যাকেজটি কনসোলে থেকে যায়; এর বদলে একটি কম্পিউটার থেকে স্ট্রিম ও ইনস্টল দিয়ে ইনস্টল করুন।",
