"netdoctor.hint.cause_source": "নেটওয়ার্ক নয়, এই কম্পিউটারে ফাইল পড়াই একে ধীর করছে: USB বা হার্ড ড্রাইভ, নেটওয়ার্ক শেয়ার (NAS) বা আর্কাইভ আনপ্যাক করা লিঙ্কের চেয়ে ধীর। আগে গেমটি অভ্যন্তরীণ SSD-তে কপি করলে, বা আর্কাইভ আনপ্যাক করে তার ফাইল আপলোড করলে পূর্ণ গতি পাওয়া যায়।",
"netdoctor.hint.cause_disk": "নেটওয়ার্ক নয়, PS5-এর ড্রাইভই একে ধীর করছে: বাহ্যিক USB ড্রাইভ, প্রায় পূর্ণ ড্রাইভ বা হাজার হাজার ছোট ফাইল (প্রতিটির নিজস্ব সময় লাগে) লিঙ্ক যত দ্রুত দেয় তার চেয়ে ধীরে লেখে। গেম ইমেজ (.ffpkg বা .exfat) একটি ফাইল হিসেবে যায়।",
"netdoctor.hint.cause_workers": "PS5 এখনো যা পেয়েছে তা লিখছে, নেটওয়ার্কের জন্য অপেক্ষা করছে না। অনেক ছোট ফাইলে প্রতিটির নিজস্ব সময় লাগে; গেম ইমেজ (.ffpkg বা .exfat) একটি ফাইল হিসেবে যায়।",
"netdoctor.hint.cause_cap": "আপলোড গতির সীমা (প্রায় {cap} MiB/s, এই স্ক্রিনে ও সেটিংসে) একে ধীর করছে। সরাতে এটি 0 করুন।",
"profile.np.confirm_body_v2": "np-fake-signin, {user}-এর জন্য PlayStation Network সাইন-ইন ফাইল ও সেটিংস PS5-এ লেখে। Sony-কে কিছু পাঠানো হয় না। এরপর PS5 আবার চালু করুন।",
"profile.np.side_effect": "জানা পার্শ্বপ্রতিক্রিয়া: এরপর কিছু কনসোল যেকোনো গেম খোলার আগে \"PS5 কনসোল সীমাবদ্ধতা সাময়িকভাবে বন্ধ করুন\" চায়, এবং সেটিংস > ব্যবহারকারী ও অ্যাকাউন্ট > অন্যান্য > সাইন আউট ধূসর থেকে যেতে পারে। np-fake-signin PS5-এ যা বদলায় তার সবকিছুর একটি কপি অ্যাপ আগে রেখে দেয়, তাই এখানে সাইন-ইন ফিরিয়ে নিন সেটি আগের মতো করে দেয়।",
"profile.np.backing_up": "PS5-এ অ্যাকাউন্টের বর্তমান সেটিংসের একটি কপি রাখা হচ্ছে…",
"profile.np.backup_failed": "PS5 অ্যাকাউন্টের সেটিংসের কপি রাখতে পারেনি, তাই np-fake-signin চালানো হয়নি। হেল্পারটি এই অ্যাপের সংস্করণ দিয়ে বদলে আবার চেষ্টা করুন। ({error})",
"profile.np.step_restart_v2": "PS5 আবার চালু করুন। পরে ফিরিয়ে নিতে এখানে সাইন-ইন ফিরিয়ে নিন চাপুন এবং আবার চালু করুন।",
"profile.np.undo": "সাইন-ইন ফিরিয়ে নিন",
"profile.np.undo_hint": "সাইন-ইনের আগের এই অ্যাকাউন্টের সেটিংসের একটি কপি PS5-এ রাখা আছে; এটি সেটি ফিরিয়ে আনে।",
"profile.np.undo_confirm_title": "সাইন-ইন ফিরিয়ে নেবেন?",
"profile.np.undo_confirm_body": "np-fake-signin চালানোর আগে {user}-এর সেটিংস ও ফাইল যেমন ছিল তেমন ফিরিয়ে দেয়। এরপর PS5 আবার চালু করুন। সাইন-ইন করা অ্যাকাউন্ট লাগে এমন সুবিধা, যেমন রিমোট প্লে, আবার সাইন ইন না করা পর্যন্ত খুলতে নাও পারে।",
"profile.np.undoing": "সেটিংস ফিরিয়ে আনা হচ্ছে…",
"profile.np.undone": "ফিরিয়ে আনা হয়েছে ({count}টি সেটিং ও ফাইল)। শেষ করতে PS5 আবার চালু করুন।",
"profile.np.no_backup": "এই অ্যাকাউন্টে np-fake-signin-এর টেমপ্লেট সেটিংস আছে (জন্মতারিখ 1983-04-12, অফলাইন-প্রাপ্তবয়স্ক ফ্ল্যাগ বন্ধ), এবং আগের কোনো কপি এই PS5-এ নেই, তাই অ্যাপ এটি ফিরিয়ে নিতে পারে না। যদি PS5 এখন গেম খোলার আগে কনসোল সীমাবদ্ধতা সাময়িকভাবে বন্ধ করতে বলে: সেটিংস > পরিবার ও অভিভাবক নিয়ন্ত্রণ > PS5 কনসোল সীমাবদ্ধতা (পাসকোড 0000, যদি না আপনি বদলে থাকেন), এবং সেখানে সীমাবদ্ধতা তুলে দিন।",
"linkdl.lz4_title": "এই লিঙ্কটি LZ4 দিয়ে সংকুচিত",
"linkdl.image_title": "এই লিঙ্কটি একটি গেম ইমেজ",
"linkdl.lz4_help": "ps5upload ডাউনলোডের সময়ই এটি আনপ্যাক করতে পারে, ফলে PS5 আনপ্যাক করা ফাইলটি পায়। এই কম্পিউটারে কিছুই সংরক্ষিত হয় না, আর PS5-এর শুধু আনপ্যাক করা ফাইলের জায়গা লাগে।",
"linkdl.lz4_unpack": "পথেই আনপ্যাক করুন",
"linkdl.lz4_unpack_hint": "বন্ধ: .lz4 ফাইলটি PS5-এ যেমন আছে তেমনই সংরক্ষিত হয়।",
"linkdl.image_hint": "একটি {kind} গেম ইমেজ। ShadowMount+ এটি যেমন আছে তেমনই মাউন্ট করে এমন একটি ফোল্ডার থেকে যা সে স্ক্যান করে, যেমন কোনো ড্রাইভের homebrew। ফাইলটি সম্পূর্ণ হলেই কেবল সেখানে দেখা যায়।",
