"ps4move_safety": "PS4 শুধু পড়া হয়, কখনো বদলানো হয় না। এর সেভ আগে এই কম্পিউটারে কপি হয়। PS5-এ শুধু বেছে নেওয়া গেমে হাত দেওয়া হয়, প্রতিটির সেভ বদলানোর আগে ব্যাকআপ হয়, আর অন্য কিছু (ইউজার, সিস্টেম ফাইল, ট্রফি) বদলায় না।",
