"mesh_rp_started": "{name} এই কনসোলে খেলা শুরু করেছে",
"rp_keys_body3": "কীবোর্ডে খেলতে ছবিতে ক্লিক করুন; Esc পয়েন্টার ফিরিয়ে দেয়। ফুল স্ক্রিনের জন্য ডাবল-ক্লিক করুন; সেখানে ছোট Esc হলো সার্কেল, আর Esc চেপে ধরলে ফুল স্ক্রিন থেকে বের হয়। কী, শব্দ ও আরও কিছু সেটিংসে।",
"rp_play_description2": "এই অ্যাপে একটি PS5 স্ট্রিম করুন এবং কন্ট্রোলার, কীবোর্ড বা টাচ দিয়ে খেলুন। এটি নিজেই রেস্ট মোড থেকে কনসোল জাগায় এবং অন্য স্ক্রিন ব্যবহারের সময়ও খেলা চালু রাখে।",
