"dump_decrypt_risk_body": "ডিক্রিপ্ট করতে হেল্পার প্রতিটি এক্সিকিউটেবলের জন্য সিস্টেমের এমন একটি অংশ অল্প সময়ের জন্য বদলায় যা সব প্রোগ্রাম ব্যবহার করে। ঠিক তখন গেম কোনো ফাইল পড়লে কনসোল ফ্রিজ হয়ে জোর করে বন্ধ করতে হতে পারে। চলার সময় গেমের স্টার্ট স্ক্রিনেই থাকুন। কেবল 13.60 পর্যন্ত ফার্মওয়্যার; নতুন ফার্মওয়্যারে ডাম্প সাধারণ কপি।",
"dump_fself": "নকল-স্বাক্ষরিত কপিও তৈরি করুন (ব্যাকপোর্টের জন্য)",
