"collection.send_many_body_v2": "প্রতিটি PS5 যা নেই তা পায়: গেমের প্যাকেজ, বা তার ফোল্ডার, ইমেজ বা আর্কাইভ, আর যে গেমগুলো আছে সেগুলোর নতুন আপডেট ও DLC। প্যাকেজ এই কম্পিউটার থেকে স্ট্রিম হয়; বাকিগুলো «আপলোড ও ইনস্টল»-এ বেছে নেওয়া ড্রাইভের homebrew ফোল্ডারে আপলোড হয়।",
"first_run_step4_body_v3": ".ffpkg গেম ইমেজসহ একটি USB স্টিক আপনার PS5-এ লাগান, ShadowMount+ সেগুলো অটো-মাউন্ট করবে — সেগুলো গেম-এ দেখা যাবে। অন্য ফাইল পাঠাতে বা .pkg প্যাকেজ ইনস্টল করতে «আপলোড ও ইনস্টল» ব্যবহার করুন।",
"first_run_go_upload_v2": "«আপলোড ও ইনস্টল» খুলুন",
"fpkg.aboutFake_v2": "ফলাফল একটি নকল প্যাকেজ, তাই ইনস্টলের আগে কনসোলে নকল-প্যাকেজ সাপোর্ট লোড থাকতে হবে: kstuff (PS5 নকল-প্যাকেজ সাপোর্টসহ সংস্করণ), a53_ppr_install_fast.elf এবং shadowmountplus.elf, এই ক্রমে। «আপলোড ও ইনস্টল» স্ক্রিনেও ইনস্টল বোতামের পাশে একই কথা বলা আছে।",
"fpkg.openUpload_v2": "«আপলোড ও ইনস্টল» খুলুন",
"connection_step3_hint_v3": "«আপলোড ও ইনস্টল» খুলুন এবং একটি গেম ফোল্ডার, .exfat বা .ffpkg ইমেজ, বা .pkg প্যাকেজ ছেড়ে দিন। আপনার পাঠানো ইমেজ ও ফোল্ডার «গেম»-এ সেই গেমের পেজে তালিকাভুক্ত থাকে, যেখানে «মাউন্ট» সেগুলো PS5-এর হোম স্ক্রিনে রাখে।",
"connection_go_upload_v2": "«আপলোড ও ইনস্টল» খুলুন",
"netdoctor.speed_cap.on.fix_v2": "দরকার না হলে «আপলোড ও ইনস্টল»-এ সীমাটি সরিয়ে দিন।",
"payloads_fpkg_ppr_note_v2": "নকল প্যাকেজ ইনস্টল করতে a53_ppr_install_fast.elf-ও লাগে, যা এই তালিকায় নেই: এর কোনো ডাউনলোড প্রকাশিত নেই, এটি GitHub-এর সোর্স থেকে তৈরি করতে হয়। «আপলোড ও ইনস্টল» স্ক্রিনে নকল প্যাকেজের যা যা লাগে সব ক্রমানুসারে দেওয়া আছে।",
"fs_extract_next_pkgs_v2": "এতে {n}টি প্যাকেজ আছে: «আপলোড ও ইনস্টল» থেকে বা এখানে সেগুলোর সারি থেকে ইনস্টল করুন।",
"game_hub_no_addons_v2": "এই গেমের জন্য কোনো DLC প্যাকেজ প্রস্তুত নেই। «আপলোড ও ইনস্টল» থেকে একটি পাঠান।",
