"bandwidth_cap_off_hint_v3": "কোনো সীমা নেই। আপলোড আপনার Wi-Fi/LAN ভরিয়ে অন্য ডিভাইস ধীর করলে একটি সীমা দিন। এটি পরের আপলোড থেকে সব আপলোডে প্রযোজ্য — «আপলোড ও ইনস্টল», কিউ ও ফাইলস থেকে।",
"queue_links_cleared_body_v2": "রিস্টার্টের পর {n}টি ইনস্টল লিংক রাখা হয়নি — লিংক কখনো ডিস্কে সংরক্ষণ করা হয় না। «আপলোড ও ইনস্টল» থেকে আবার যোগ করুন।",
"game_hub_no_updates_v2": "এই গেমের জন্য কোনো আপডেট প্যাকেজ প্রস্তুত নেই। «আপলোড ও ইনস্টল» থেকে একটি পাঠান।",
"pkglib.fpkgsupport.firmware": "11.60-এর পরের ফার্মওয়্যারে PS5 নকল প্যাকেজ (PS5 FPKG) এখনও সমর্থিত নয়: সেগুলো ইনস্টল হয়, কিন্তু গেম চালু হয় না। PS4 নকল প্যাকেজে কোনো সমস্যা নেই।",
"upload_drop_here3": "প্যাকেজ, গেম, ডিস্ক ইমেজ, আর্কাইভ বা যেকোনো ফাইল এখানে ছাড়ুন বা বেছে নিন",
"upload_pick_here_mobile3": "প্যাকেজ, গেম, ডিস্ক ইমেজ, আর্কাইভ বা যেকোনো ফাইল বেছে নিন",
"upload_drop_kind_pkg": "প্যাকেজ (.pkg, .fpkg): গেম, আপডেট বা DLC হিসেবে ইনস্টল হয়, এখান থেকে স্ট্রিম হয়ে বা আগে আপলোড হয়ে।",
"upload_drop_kind_game": "গেম ফোল্ডার ও গেম ডাম্প: PS5-এ কপি হয়; হোম স্ক্রিনে রাখা যায়।",
"upload_drop_kind_image": "ডিস্ক ইমেজ (.exfat, .ffpkg, .ffpfs, .ffpfsc): PS5-এ কপি হয়; মাউন্ট করা যায়।",
"upload_drop_kind_archive": "আর্কাইভ (.zip, .7z, .rar): PS5-এ এক্সট্র্যাক্ট হয়।",
"upload_drop_kind_other": "অন্য যেকোনো ফাইল বা ফোল্ডার: যেমন আছে তেমন কপি হয়।",
"upload_other_ways": "অথবা একটি প্যাকেজ ইনস্টল করুন:",
"queue_stream_fail_hint": "«স্ট্রিম ও ইনস্টল»-এ PS5 এই কম্পিউটার থেকে প্যাকেজটি নিয়ে আসে। বারবার ব্যর্থ হলে, লোকাল নেটওয়ার্কে এই কম্পিউটারের ফায়ারওয়ালে ps5upload-কে অনুমতি দিন যাতে PS5 এটির কাছে পৌঁছাতে পারে, অথবা «আপলোড করে আবার চেষ্টা করুন» ব্যবহার করুন, যা প্যাকেজটি আগে PS5-এ কপি করে তারপর ইনস্টল করে।",
"err_install_enoent_generic_v2": "ইনস্টলের সময় Sony-র ইনস্টলার প্রয়োজনীয় একটি ফাইল খুলতে পারেনি (kernel ত্রুটি 0x80020002 = ENOENT)। এটি DLC pkg হলে, বেস গেম এখনও ইনস্টল নেই — প্রথমে বেস ইনস্টল করুন। নতুবা আপলোড ও ইনস্টলের মাঝে প্রস্তুত রাখা প্যাকেজটি মুছে গিয়ে থাকতে পারে; ইনস্টল একবার আবার চেষ্টা করুন। বারবার ব্যর্থ হলে, «আপলোড ও ইনস্টল»-এ «স্ট্রিম ও ইনস্টল» দিয়ে ইনস্টল করুন, যা প্যাকেজটি আগে কনসোলে কপি না করে সরাসরি এই কম্পিউটার থেকে পাঠায়।",
"upload_convert_first": "আগে রূপান্তর করুন",
"batch_convert_first_hint": "টিক দেওয়া গেম, ফোল্ডার ও ইমেজ ওয়ার্কশপে খুলুন, আগে সেগুলো থেকে প্যাকেজ, ইমেজ বা ফোল্ডার তৈরি করতে",
"add_sources_pick_folders": "এক বা একাধিক ফোল্ডার বেছে নিন",
"add_sources_pick_files": "এক বা একাধিক ফাইল বেছে নিন",
"workshop_add_locked": "একটি গেম তৈরি হচ্ছে: এখন বেছে নেওয়া গেমগুলো কিউতে অপেক্ষা করবে।",
"workshop_add_hint": "এখানে পরীক্ষা করতে একটি গেম বেছে নিন। একাধিক গেম, বা গেমের একটি ফোল্ডার, কিউতে যায় এবং একটির পর একটি তৈরি হয়।",
"workshop_description_v2": "PS5-এ যাওয়ার আগে গেমের ফরম্যাট বদলান: একটি প্যাকেজ (.pkg), গেম ইমেজ (.exfat, .ffpkg, বা ছোট .ffpfsc) বা সাধারণ ফোল্ডার তৈরি করুন, অথবা কোনো ইমেজ বা প্যাকেজের ভেতরে দেখে তার ফাইল বদলান। কাজটি এই কম্পিউটারে হয়। গেম যেমন আছে তেমন পাঠাতে {send} ব্যবহার করুন।",
"cq_title_v2": "⑤ কিউ",
"cq_about": "এই কম্পিউটারে একটির পর একটি তৈরি হয়, প্রতিটি যোগ করার সময় ②, ③ ও ④ যেমন সেট ছিল সেভাবে। কিউ চলার সময়ও ①-এ আরও যোগ করুন; অপেক্ষমাণ গেম তার অপশন বোতাম দিয়ে বদলান।",
"cq_then_send": "ইনস্টল বা আপলোডের জন্য সেট করা গেম তৈরি হয়ে গেলে {send}-এর কিউতে চলে যায়।",
"cq_open_send": "{send} খুলুন",
"backup_alike_toggle": "{since} থেকে {count}টি একই রকম কপি। পুরোনো একটি রিস্টোর করতে প্রতিটি দেখান।",
"add_sources_no_picker": "এই বিল্ড এই কম্পিউটার ব্রাউজ করতে পারে না — ইঞ্জিন দেখতে পায় এমন একটি পাথ লিখুন।",
"collection.empty_body_v2": "এর ভেতরের প্যাকেজ, গেম ফোল্ডার, গেম ইমেজ ও আর্কাইভ খুঁজে গেম অনুযায়ী সাজানো হয়। ফোল্ডারে কিছুই বদলায় না। এই ডিভাইসের ফোল্ডার, বাহ্যিক ড্রাইভ বা NAS বা সার্ভারের (SMB, FTP, SFTP, WebDAV) ফোল্ডার—সবই চলে।",
