"queue_auto_start_tooltip": "চালু: “ইনস্টল”, “এখনই আপলোড” এবং “পাঠান” এই কনসোলের পুরো সারি ক্রমানুসারে শুরু করে। বন্ধ: এগুলো শুধু সারিতে যোগ করে, আর “সারি শুরু করুন” না চাপা পর্যন্ত কিছুই চলে না।",
"queue_auto_start_hint": "চালু: “ইনস্টল”, “এখনই আপলোড” এবং “পাঠান” কনসোলের পুরো সারি ক্রমানুসারে শুরু করে — শুধু আপনি এইমাত্র যা যোগ করেছেন তা নয়। বন্ধ: এগুলো শুধু সারিতে যোগ করে, আর “সারি শুরু করুন” না চাপা পর্যন্ত কিছুই চলে না। ডিফল্টভাবে চালু।",
